import{_ as t,o,c as a,a2 as r}from"./chunks/framework.D3GK3dQI.js";const u=JSON.parse('{"title":"ADR-004: OpenTelemetry (OTEL) Metrics Support","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/004-otel-metrics.md","filePath":"adrs/004-otel-metrics.md"}'),i={name:"adrs/004-otel-metrics.md"};function s(n,e,c,l,d,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-004-opentelemetry-otel-metrics-support" tabindex="-1">ADR-004: OpenTelemetry (OTEL) Metrics Support <a class="header-anchor" href="#adr-004-opentelemetry-otel-metrics-support" aria-label="Permalink to &quot;ADR-004: OpenTelemetry (OTEL) Metrics Support&quot;">​</a></h1><p><strong>Date:</strong> 2026-06-06<br><strong>Status:</strong> Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>While Prometheus is a standard for metric scraping, OpenTelemetry (OTEL) is becoming the industry standard for pushing metrics, traces, and logs. We need to support OTEL to allow sending <code>exposed_route_info</code> metrics via an OTLP pipeline.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>We will add support for pushing metrics via an OTLP gRPC exporter.</p><ol><li><strong>Activation:</strong> OTEL metrics will be enabled via the <code>ENABLE_OTEL=true</code> environment variable. By default, the exporter uses <code>localhost:4317</code> for the OTEL Collector endpoint (configurable via standard <code>OTEL_EXPORTER_OTLP_ENDPOINT</code> env var).</li><li><strong>Mechanism:</strong> Unlike Prometheus (which scrapes an HTTP endpoint), OTEL SDKs support an asynchronous observation model. We will register an <code>Int64ObservableGauge</code> named <code>exposed_route_info</code>.</li><li><strong>Execution:</strong> The OTEL SDK triggers a callback every 15 seconds. The callback invokes <code>mapper.GetExposedRoutes()</code> and observes the same 12 attributes documented for the Prometheus metric.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><strong>Positive:</strong> We can export metrics directly to observability backends (Datadog, Dynatrace, New Relic) via an OTEL Collector without exposing a scrape endpoint if we choose not to.</li><li><strong>Negative:</strong> OTEL dependencies add weight to the Go module. <code>GetExposedRoutes()</code> is called by both Prometheus scrapes and OTEL collection cycles, with work proportional to the cached route graph.</li></ul><h2 id="traceability" tabindex="-1">Traceability <a class="header-anchor" href="#traceability" aria-label="Permalink to &quot;Traceability&quot;">​</a></h2><p>Code implementing this strategy MUST reference this document. Expected locations: <code>internal/metrics/otel.go</code>.</p>',11)])])}const m=t(i,[["render",s]]);export{u as __pageData,m as default};
